              <div>
                <strong>Fast follow-up</strong>
                <span>Use your email and phone details so we can reach you quickly.</span>
              </div>
            </li>
            <li>
              <span class="point-icon" aria-hidden="true">3</span>
              <div>
                <strong>Simple, secure intake</strong>
                <span>Only the information needed to contact you is collected here.</span>
              </div>
            </li>
          </ul>
        </div>

        <div class="form-card">
          <h2 class="card-title">Contact support</h2>
          <p class="card-copy">Complete the form below and we’ll get back to you soon.</p>
          <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required fields</p>

          <form id="support-form" novalidate>
            <div class="form-field">
              <label for="full-name">Full name <span class="required-indicator" aria-hidden="true">*</span></label>
              <input
                id="full-name"
                name="fullName"
                type="text"
                autocomplete="name"
                required
                aria-describedby="full-name-error"
              >
              <p class="error-message" id="full-name-error"></p>
            </div>

            <div class="form-field">
              <label for="email-address">Email address <span class="required-indicator" aria-hidden="true">*</span></label>
              <input
                id="email-address"
                name="email"
                type="email"
                autocomplete="email"
                inputmode="email"
                required
                aria-describedby="email-address-error"
              >
              <p class="error-message" id="email-address-error"></p>
            </div>

            <div class="form-field">
              <label for="phone-number">Phone number</label>
              <input
                id="phone-number"
                name="phone"
                type="tel"
                autocomplete="tel"
                inputmode="tel"
                aria-describedby="phone-number-help phone-number-error"
              >
              <p class="helper-text" id="phone-number-help">Optional. Enter 10 to 15 digits; spaces, dashes, parentheses, and a leading + are accepted.</p>
              <p class="error-message" id="phone-number-error"></p>
            </div>

            <button class="submit-button" type="submit">Send request</button>
            <p class="form-status" id="form-status" role="status"></p>
          </form>
        </div>
      </section>
    </div>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        validate(value) {
          if (!value.trim()) {
            return 'Error: Enter your full name.';
          }
          return '';
        }
      },
      email: {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-address-error'),
        validate(value) {
          if (!value.trim()) {
            return 'Error: Enter your email address.';
          }
          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
            return 'Error: Enter a valid email address, such as name@example.com.';
          }
          return '';
        }
      },
      phone: {
        input: document.getElementById('phone-number'),
        error: document.getElementById('phone-number-error'),
        validate(value) {
          const trimmed = value.trim();

          if (!trimmed) {
            return '';
          }

          const digits = trimmed.replace(/\D/g, '');
          const formatPattern = /^\+?[0-9().\-\s]+$/;

          if (!formatPattern.test(trimmed) || digits.length < 10 || digits.length > 15) {
            return 'Error: Enter a phone number with 10 to 15 digits using only numbers, spaces, dashes, parentheses, or a leading +.';
          }

          return '';
        }
      }
    };

    const status = document.getElementById('form-status');

    function setFieldState(fieldConfig, message) {
      fieldConfig.error.textContent = message;
      if (message) {
        fieldConfig.input.setAttribute('aria-invalid', 'true');
      } else {
        fieldConfig.input.removeAttribute('aria-invalid');
      }
    }

    function validateField(fieldConfig) {
      const message = fieldConfig.validate(fieldConfig.input.value);
      setFieldState(fieldConfig, message);
      return message;
    }

    Object.values(fields).forEach((fieldConfig) => {
      fieldConfig.input.addEventListener('blur', () => {
        validateField(fieldConfig);
      });

      fieldConfig.input.addEventListener('input', () => {
        if (fieldConfig.error.textContent) {
          validateField(fieldConfig);
        } else if (fieldConfig.input.getAttribute('aria-invalid') === 'true') {
          setFieldState(fieldConfig, '');
        }
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      status.textContent = '';

      const validationOrder = [fields.fullName, fields.email, fields.phone];
      const messages = validationOrder.map((fieldConfig) => validateField(fieldConfig));
      const firstInvalidField = validationOrder.find((fieldConfig, index) => messages[index]);

      if (firstInvalidField) {
        firstInvalidField.input.focus();
        return;
      }

      status.textContent = 'Your support request is ready to send.';
      form.reset();
      Object.values(fields).forEach((fieldConfig) => setFieldState(fieldConfig, ''));
    });
  </script>
