404.   <script>
405.     const form = document.getElementById('support-form');
406.     const fields = {
407.       fullName: {
408.         input: document.getElementById('full-name'),
409.         error: document.getElementById('full-name-error'),
410.         validate(value) {
411.           if (!value.trim()) {
412.             return 'Error: Enter your full name.';
413.           }
414.           return '';
415.         }
416.       },
417.       email: {
418.         input: document.getElementById('email-address'),
419.         error: document.getElementById('email-address-error'),
420.         validate(value) {
421.           if (!value.trim()) {
422.             return 'Error: Enter your email address.';
423.           }
424.           if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
425.             return 'Error: Enter a valid email address, such as name@example.com.';
426.           }
427.           return '';
428.         }
429.       },
430.       phone: {
431.         input: document.getElementById('phone-number'),
432.         error: document.getElementById('phone-number-error'),
433.         validate(value) {
434.           const trimmed = value.trim();
435. 
436.           if (!trimmed) {
437.             return '';
438.           }
439. 
440.           const digits = trimmed.replace(/\D/g, '');
441.           const formatPattern = /^\+?[0-9().\-\s]+$/;
442. 
443.           if (!formatPattern.test(trimmed) || digits.length < 10 || digits.length > 15) {
444.             return 'Error: Enter a phone number with 10 to 15 digits using only numbers, spaces, dashes, parentheses, or a leading +.';
445.           }
446. 
447.           return '';
448.         }
449.       }
450.     };
451. 
452.     const status = document.getElementById('form-status');
453. 
454.     function setFieldState(fieldConfig, message) {
455.       fieldConfig.error.textContent = message;
456.       if (message) {
457.         fieldConfig.input.setAttribute('aria-invalid', 'true');
458.       } else {
459.         fieldConfig.input.removeAttribute('aria-invalid');
460.       }
461.     }
462. 
463.     function validateField(fieldConfig) {
464.       const message = fieldConfig.validate(fieldConfig.input.value);
465.       setFieldState(fieldConfig, message);
466.       return message;
467.     }
468. 
469.     Object.values(fields).forEach((fieldConfig) => {
470.       fieldConfig.input.addEventListener('blur', () => {
471.         validateField(fieldConfig);
472.       });
473. 
474.       fieldConfig.input.addEventListener('input', () => {
475.         if (fieldConfig.error.textContent) {
476.           validateField(fieldConfig);
477.         } else if (fieldConfig.input.getAttribute('aria-invalid') === 'true') {
478.           setFieldState(fieldConfig, '');
479.         }
480.       });
481.     });
482. 
483.     form.addEventListener('submit', (event) => {
484.       event.preventDefault();
485.       status.textContent = '';
486. 
487.       const validationOrder = [fields.fullName, fields.email, fields.phone];
488.       const messages = validationOrder.map((fieldConfig) => validateField(fieldConfig));
489.       const firstInvalidField = validationOrder.find((fieldConfig, index) => messages[index]);
490. 
491.       if (firstInvalidField) {
492.         firstInvalidField.input.focus();
493.         return;
494.       }
495. 
496.       status.textContent = 'Your support request is ready to send.';
497.       form.reset();
498.       Object.values(fields).forEach((fieldConfig) => setFieldState(fieldConfig, ''));
